/*
const MAX_POWER = 80;

const left = Math.max(
    -MAX_POWER,
    Math.min(MAX_POWER, Number(msg.payload?.left) || 0)
);

const right = Math.max(
    -MAX_POWER,
    Math.min(MAX_POWER, Number(msg.payload?.right) || 0)
);
*/

const left = Math.max(-100, Math.min(100, msg.payload.left ?? 0));
const right = Math.max(-100, Math.min(100, msg.payload.right ?? 0));

const leftForward = left > 0 ? 1 : 0;
const leftBackward = left < 0 ? 1 : 0;

const rightForward = right > 0 ? 1 : 0;
const rightBackward = right < 0 ? 1 : 0;

const leftSpeed = Math.abs(left);
const rightSpeed = Math.abs(right);

return [
    { payload: leftForward },    // IN1
    { payload: leftBackward },   // IN2
    { payload: leftSpeed },      // ENA PWM
    { payload: rightForward },   // IN3
    { payload: rightBackward },  // IN4
    { payload: rightSpeed }      // ENB PWM
];

const perception = msg.payload;

const distance = perception?.distance?.front;
const ir = perception?.ir ?? {};

// ========================================
// Configuración global
// ========================================

const distances = env.get("DISTANCES");
const situations = env.get("SITUATIONS");
const severities = env.get("SEVERITIES");


// ========================================
// Validación de configuración global
// ========================================

if (
    !distances ||
    !situations ||
    !severities
) {
    node.error(
        "Configuración de evaluación incompleta",
        msg
    );

    return null;
}


// ========================================
// Recuperación de umbrales
// ========================================

const EMERGENCY_DISTANCE =
    distances.DISTANCE_EMERGENCY_CM;

const CRITICAL_DISTANCE =
    distances.DISTANCE_CRITICAL_CM;

const CAUTION_DISTANCE =
    distances.DISTANCE_CAUTION_CM;


// ========================================
// Validación de umbrales
// ========================================

const validEmergencyDistance =
    typeof EMERGENCY_DISTANCE === "number" &&
    Number.isFinite(EMERGENCY_DISTANCE) &&
    EMERGENCY_DISTANCE > 0;

const validCriticalDistance =
    typeof CRITICAL_DISTANCE === "number" &&
    Number.isFinite(CRITICAL_DISTANCE) &&
    CRITICAL_DISTANCE > 0;

const validCautionDistance =
    typeof CAUTION_DISTANCE === "number" &&
    Number.isFinite(CAUTION_DISTANCE) &&
    CAUTION_DISTANCE > 0;

if (
    !validEmergencyDistance ||
    !validCriticalDistance ||
    !validCautionDistance
) {
    node.error(
        "Los umbrales de distancia deben ser números positivos y finitos",
        msg
    );

    return null;
}


// Los umbrales deben cumplir:
//
// 0 < EMERGENCY < CRITICAL < CAUTION

if (
    EMERGENCY_DISTANCE >= CRITICAL_DISTANCE ||
    CRITICAL_DISTANCE >= CAUTION_DISTANCE
) {
    node.error(
        "Configuración de distancias inválida: debe cumplirse 0 < EMERGENCY < CRITICAL < CAUTION",
        msg
    );

    return null;
}


// ========================================
// Validación de distancia percibida
// ========================================

const validDistance =
    typeof distance === "number" &&
    Number.isFinite(distance) &&
    distance >= 0;

if (!validDistance) {

    node.warn(
        `Distancia frontal inválida: ${distance}`
    );

    msg.payload = {
        situation: situations.SENSOR_ERROR,
        severity: severities.CRITICAL,
        perception
    };

    return msg;
}


// ========================================
// Interpretación de sensores IR
// ========================================

const leftDetected =
    ir.leftOuter === 1 ||
    ir.leftInner === 1;

const rightDetected =
    ir.rightInner === 1 ||
    ir.rightOuter === 1;


// ========================================
// Estado inicial
// ========================================

let situation = situations.FREE;
let severity = severities.NONE;


// ========================================
// Evaluación del entorno
//
// Prioridad:
//
// 1. Emergencia frontal
// 2. Obstáculo frontal crítico
// 3. Precaución frontal
// 4. Bloqueo IR izquierda + derecha
// 5. Obstáculo IR izquierdo
// 6. Obstáculo IR derecho
// 7. Camino libre
// ========================================

if (distance <= EMERGENCY_DISTANCE) {

    situation = situations.EMERGENCY_FRONT;
    severity = severities.CRITICAL;

} else if (distance <= CRITICAL_DISTANCE) {

    situation = situations.OBSTACLE_FRONT;
    severity = severities.CRITICAL;

} else if (distance <= CAUTION_DISTANCE) {

    situation = situations.CAUTION;
    severity = severities.CAUTION;

} else if (leftDetected && rightDetected) {

    situation = situations.BLOCKED;
    severity = severities.CRITICAL;

} else if (leftDetected) {

    situation = situations.OBSTACLE_LEFT;
    severity = severities.CAUTION;

} else if (rightDetected) {

    situation = situations.OBSTACLE_RIGHT;
    severity = severities.CAUTION;
}


// ========================================
// Resultado de evaluación
// ========================================

msg.payload = {
    situation,
    severity,
    perception
};

return msg;

const evaluation = msg.payload;

const situation = evaluation?.situation;
const severity = evaluation?.severity;
const perception = evaluation?.perception ?? {};
const ir = perception?.ir ?? {};


// ========================================
// Configuración global
// ========================================

const situations = env.get("SITUATIONS");
const states = env.get("NAVIGATION_STATES");
const powers = env.get("AUTO_POWERS");

// ========================================
// Validación de configuración
// ========================================

if (!situations || typeof situations !== "object") {
    node.error(
        "SITUATIONS no existe o no es un objeto válido",
        msg
    );
    return null;
}

if (!states || typeof states !== "object") {
    node.error(
        "NAVIGATION_STATES no existe o no es un objeto válido",
        msg
    );
    return null;
}

if (!powers || typeof powers !== "object") {
    node.error(
        "AUTO_POWERS no existe o no es un objeto válido",
        msg
    );
    return null;
}

const requiredPowers = [
    "FORWARD",
    "CAUTION",
    "REVERSE",
    "TURN"
];

const invalidPower = requiredPowers.find(key => {
    const value = powers[key];

    return (
        typeof value !== "number" ||
        !Number.isFinite(value) ||
        value < 0 ||
        value > 90
    );
});

if (invalidPower) {
    node.error(
        `AUTO_POWERS.${invalidPower} debe ser un número entre 0 y 90`,
        msg
    );
    return null;
}

if (!situation) {
    node.error(
        "La evaluación no contiene msg.payload.situation",
        msg
    );
    return null;
}

// ========================================
// Estado persistente de navegación
// ========================================

const currentState =
    context.get("navigationState") ??
    states.STOPPED;

const lastCommand =
    context.get("lastCommand") ?? {
        left: 0,
        right: 0
    };

let lastTurn =
    context.get("lastTurn") ??
    states.TURNING_LEFT;

// ========================================
// Interpretación lateral
// ========================================

const leftDetected =
    ir.leftOuter === 1 ||
    ir.leftInner === 1;

const rightDetected =
    ir.rightInner === 1 ||
    ir.rightOuter === 1;


// ========================================
// Comandos disponibles
// ========================================

const COMMANDS = {
    STOP: {
        left: 0,
        right: 0
    },

    FORWARD: {
        left: powers.FORWARD,
        right: powers.FORWARD
    },

    CAUTION: {
        left: powers.CAUTION,
        right: powers.CAUTION
    },

    REVERSE: {
        left: -powers.REVERSE,
        right: -powers.REVERSE
    },

    TURN_LEFT: {
        left: -powers.TURN,
        right: powers.TURN
    },

    TURN_RIGHT: {
        left: powers.TURN,
        right: -powers.TURN
    }
};


// ========================================
// Selección del lado de escape
// ========================================

function chooseTurnState() {

    /*
     * Obstáculo a la izquierda:
     * escapar hacia la derecha.
     */
    if (leftDetected && !rightDetected) {
        return states.TURNING_RIGHT;
    }

    /*
     * Obstáculo a la derecha:
     * escapar hacia la izquierda.
     */
    if (rightDetected && !leftDetected) {
        return states.TURNING_LEFT;
    }

    /*
     * Si ambos lados están libres,
     * alterna la dirección de giro.
     */
    if (!leftDetected && !rightDetected) {
        return lastTurn === states.TURNING_LEFT
            ? states.TURNING_RIGHT
            : states.TURNING_LEFT;
    }

    /*
     * Ambos lados están bloqueados.
     */
    return states.REVERSING;
}


// ========================================
// Decisión de navegación
// ========================================

let nextState = currentState;
let command = null;

// ----------------------------------------
// Error de percepción: detener
// ----------------------------------------

if (situation === situations.SENSOR_ERROR) {
    nextState = states.STOPPED;
    command = COMMANDS.STOP;

    // ----------------------------------------
    // Robot girando
    // ----------------------------------------

} else if (
    currentState === states.TURNING_LEFT ||
    currentState === states.TURNING_RIGHT
) {

    /*
     * Termina el giro cuando el entorno
     * frontal vuelve a estar libre.
     */
    if (situation === situations.FREE) {
        nextState = states.MOVING_FORWARD;
        command = COMMANDS.FORWARD;

        /*
         * Si queda completamente bloqueado,
         * retrocede.
         */
    } else if (situation === situations.BLOCKED) {
        nextState = states.REVERSING;
        command = COMMANDS.REVERSE;

    } else {

        /*
         * Sigue ejecutando el giro actual.
         * No reenvía una orden redundante.
         */
        command = null;
    }


    // ----------------------------------------
    // Robot retrocediendo
    // ----------------------------------------

} else if (currentState === states.REVERSING) {

    /*
     * Sigue retrocediendo mientras permanezca
     * bloqueado o en emergencia.
     */
    if (
        situation === situations.EMERGENCY_FRONT ||
        situation === situations.BLOCKED
    ) {

        command = null;

    } else {

        /*
         * Cuando consigue separarse,
         * comienza una rotación evasiva.
         */
        nextState = chooseTurnState();

        if (nextState === states.TURNING_LEFT) {

            command = COMMANDS.TURN_LEFT;

        } else if (
            nextState === states.TURNING_RIGHT
        ) {

            command = COMMANDS.TURN_RIGHT;

        } else {

            nextState = states.REVERSING;
            command = COMMANDS.REVERSE;
        }
    }


    // ----------------------------------------
    // Emergencia frontal
    // ----------------------------------------

} else if (
    situation === situations.EMERGENCY_FRONT
) {

    nextState = chooseTurnState();

    if (nextState === states.TURNING_LEFT) {

        command = COMMANDS.TURN_LEFT;

    } else if (
        nextState === states.TURNING_RIGHT
    ) {

        command = COMMANDS.TURN_RIGHT;

    } else {

        nextState = states.REVERSING;
        command = COMMANDS.REVERSE;
    }


    // ----------------------------------------
    // Obstáculo frontal
    // ----------------------------------------

} else if (
    situation === situations.OBSTACLE_FRONT
) {

    nextState = chooseTurnState();

    if (nextState === states.TURNING_LEFT) {

        command = COMMANDS.TURN_LEFT;

    } else if (
        nextState === states.TURNING_RIGHT
    ) {

        command = COMMANDS.TURN_RIGHT;

    } else {

        nextState = states.REVERSING;
        command = COMMANDS.REVERSE;
    }


    // ----------------------------------------
    // Obstáculo izquierdo
    // ----------------------------------------

} else if (
    situation === situations.OBSTACLE_LEFT
) {

    nextState = states.TURNING_RIGHT;
    command = COMMANDS.TURN_RIGHT;


    // ----------------------------------------
    // Obstáculo derecho
    // ----------------------------------------

} else if (
    situation === situations.OBSTACLE_RIGHT
) {

    nextState = states.TURNING_LEFT;
    command = COMMANDS.TURN_LEFT;


    // ----------------------------------------
    // Bloqueo completo
    // ----------------------------------------

} else if (
    situation === situations.BLOCKED
) {

    nextState = states.REVERSING;
    command = COMMANDS.REVERSE;


    // ----------------------------------------
    // Zona de precaución
    // ----------------------------------------

} else if (
    situation === situations.CAUTION
) {

    nextState = states.MOVING_CAUTION;

    if (
        currentState !== states.MOVING_CAUTION
    ) {
        command = COMMANDS.CAUTION;
    }


    // ----------------------------------------
    // Camino libre
    // ----------------------------------------

} else if (
    situation === situations.FREE
) {

    nextState = states.MOVING_FORWARD;

    if (
        currentState !== states.MOVING_FORWARD
    ) {
        command = COMMANDS.FORWARD;
    }


    // ----------------------------------------
    // Situación desconocida: detener
    // ----------------------------------------

} else {

    node.warn(
        `Situación desconocida: ${situation}`
    );

    nextState = states.STOPPED;
    command = COMMANDS.STOP;
}


// ========================================
// Actualización del estado
// ========================================

context.set(
    "navigationState",
    nextState
);

if (
    nextState === states.TURNING_LEFT ||
    nextState === states.TURNING_RIGHT
) {
    lastTurn = nextState;

    context.set(
        "lastTurn",
        lastTurn
    );
}


// ========================================
// No emitir órdenes innecesarias
// ========================================

if (command === null) {
    return null;
}

const sameCommand =
    command.left === lastCommand.left &&
    command.right === lastCommand.right;

if (sameCommand) {
    return null;
}

context.set(
    "lastCommand",
    {
        left: command.left,
        right: command.right
    }
);


// ========================================
// Salida hacia el Subflow L298N
// ========================================

msg.payload = {
    left: command.left,
    right: command.right
};

msg.navigation = {
    previousState: currentState,
    currentState: nextState,
    situation,
    severity
};

return msg;

// Recuperamos los valores objetivo que vienen del control manual
let targetLeft = msg.payload.left ?? 0;
let targetRight = msg.payload.right ?? 0;

// Recuperamos la velocidad anterior guardada en el contexto del nodo (o inicializamos en 0)
let currentLeft = context.get("currentLeft") || 0;
let currentRight = context.get("currentRight") || 0;

// Tasa máxima de cambio por ciclo (Step de rampa). 
// Un valor de 15 a 20 hace que la aceleración sea suave y progresiva.
const MAX_STEP = 15; 

function ramp(current, target, step) {
    if (target > current) {
        return Math.min(target, current + step);
    } else if (target < current) {
        return Math.max(target, current - step);
    }
    return target;
}

// Aplicamos la rampa a ambos lados
currentLeft = ramp(currentLeft, targetLeft, MAX_STEP);
currentRight = ramp(currentRight, targetRight, MAX_STEP);

// Guardamos los valores actuales para el próximo ciclo
context.set("currentLeft", currentLeft);
context.set("currentRight", currentRight);

// Actualizamos el payload con los valores suavizados
msg.payload = {
    left: Math.round(currentLeft),
    right: Math.round(currentRight)
};

return msg;
